import { useEffect, useState } from "react"

export const getRequestWithNativeFetch = async (url) => {
    const response = await fetch(url)

    if(!response.ok) throw new Error(`HTTP error: Status ${response.status}`)

    return response.json()
}

export default function TodoPage() {

    const [todos, setTodos] = useState(null)
    const [isLoading, setIsLoading] = useState(true)
    const [isError, setIsError] = useState(null)

    useEffect(() => {
        const fetchTodoData = async () => {
            try {
                const data = await getRequestWithNativeFetch("https://jsonplaceholder.typicode.com/todos?_limit=10")

                setTodos(data)
                setIsError(null)
            } catch(err) {
                setIsError(err.massage)
                setTodos(null)
            } finally {
                setIsLoading(false)
            }
        }
    }, [])

    return (
        <div className="h-screen w-full flex justify-center items-start">
            <p>Todo Page</p>
        </div>
    )
}
